          "Change request list",
          "Current specification document"
        ],
        "outputs": [
          "Revised specification document"
        ]
      },
      {
        "id": "A6",
        "name": "Confirm Revisions Are Acceptable",
        "actor": "Feature Owner",
        "system": "Document Repository",
        "inputs": [
